package cn.mop.api;
import cn.mop.adapters.monitoring.ZabbixVersionProtocol;
import cn.mop.adapters.monitoring.ZabbixVersionProtocol.*;
import com.fasterxml.jackson.databind.*;
import org.junit.jupiter.api.Test;
import java.net.URI;
import java.nio.charset.StandardCharsets;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
/** Isolated byte/URI checks. No local HTTP server, provider, credential or monitoring fixture is started. */
class ZabbixVersionProtocolTest {
    byte[] bytes(String value){return value.getBytes(StandardCharsets.UTF_8);}
    Result decode(String raw){return ZabbixVersionProtocol.decode(200,"application/json",bytes(raw),1);}
    String good(String version){return "{\"jsonrpc\":\"2.0\",\"result\":\""+version+"\",\"id\":1}";}
    @Test void requestIsOnlyUnauthenticatedApiVersionAndEmptyArray()throws Exception{var value=new ObjectMapper().readTree(ZabbixVersionProtocol.request(1));Set<String> fields=new HashSet<>();value.fieldNames().forEachRemaining(fields::add);assertEquals(Set.of("jsonrpc","method","params","id"),fields);assertEquals("2.0",value.get("jsonrpc").textValue());assertEquals("apiinfo.version",value.get("method").textValue());assertTrue(value.get("params").isArray());assertTrue(value.get("params").isEmpty());assertEquals(1,value.get("id").longValue());assertFalse(value.has("auth"));}
    @Test void correlationIdsAreExplicitBoundedAndEncodeWithoutRounding()throws Exception{var value=new ObjectMapper().readTree(ZabbixVersionProtocol.request(ZabbixVersionProtocol.MAX_REQUEST_ID));assertEquals(ZabbixVersionProtocol.MAX_REQUEST_ID,value.get("id").longValue());for(long id:new long[]{0,-1,Long.MAX_VALUE})assertThrows(IllegalArgumentException.class,()->ZabbixVersionProtocol.request(id));}
    @Test void supportedVersionNeverProvesMetricsPermissionsSchedulerOrTenantMapping(){var r=decode(good("7.0.31"));assertEquals(Outcome.VERSION_READ,r.outcome());assertEquals("7.0.31",r.apiVersion());assertNull(r.monitoringReady());assertFalse(r.credentialsUsed());assertFalse(r.observationsRead());assertFalse(r.serverSchedulerVerified());assertFalse(r.tenantMappingVerified());assertFalse(r.providerPermissionsVerified());}
    @Test void syntacticallyValidOtherSeriesRemainsUnsupportedNotSilentlyAccepted(){for(String version:List.of("6.0.42","7.4.8","8.0.0","0.0.0")){var result=decode(good(version));assertEquals(Outcome.UNSUPPORTED_VERSION,result.outcome());assertEquals(version,result.apiVersion());assertNull(result.monitoringReady());}}
    @Test void malformedPrereleaseLeadingZerosAndUnexpectedTextNeverEchoedAsVersion(){for(String version:List.of("7.0","07.0.31","7.00.31","7.0.031","7.0.31rc1","7.0.31 ","SYNTHETIC_SECRET_NOT_ECHOED")){var result=decode(good(version));assertEquals(Outcome.PROTOCOL_ERROR,result.outcome());assertNull(result.apiVersion());assertFalse(result.toString().contains("SYNTHETIC_SECRET_NOT_ECHOED"));}}
    @Test void mismatchedStringFloatingAndMissingIdsFailClosed(){for(String raw:List.of(good("7.0.31").replace("\"id\":1","\"id\":2"),good("7.0.31").replace("\"id\":1","\"id\":\"1\""),good("7.0.31").replace("\"id\":1","\"id\":1.0"),"{\"jsonrpc\":\"2.0\",\"result\":\"7.0.31\"}"))assertEquals(Outcome.PROTOCOL_ERROR,decode(raw).outcome());}
    @Test void redirectsAndHttpErrorsDoNotParseBodiesOrMasqueradeAsVersion(){for(int status:List.of(301,302,307,401,403,404,500,503)){var r=ZabbixVersionProtocol.decode(status,"application/json",bytes(good("7.0.31")),1);assertEquals(Outcome.HTTP_ERROR,r.outcome());assertNull(r.apiVersion());}}
    @Test void htmlAndWrongEncodingsAreRejectedDespiteValidLookingVersionJson(){for(String contentType:Arrays.asList(null,"text/html","application/xml","application/json; charset=utf-16","application/json; charset=utf-8;extra=1"))assertEquals(Outcome.PROTOCOL_ERROR,ZabbixVersionProtocol.decode(200,contentType,bytes(good("7.0.31")),1).outcome());assertEquals(Outcome.PROTOCOL_ERROR,decode("<html>7.0.31</html>").outcome());assertEquals(Outcome.PROTOCOL_ERROR,ZabbixVersionProtocol.decode(200,"application/json",new byte[]{(byte)0xc3,(byte)0x28},1).outcome());}
    @Test void acceptedJsonContentTypesStayExplicit(){for(String contentType:List.of("application/json","application/json-rpc","Application/JSON; charset=UTF-8","application/json; charset=\"utf-8\""))assertEquals(Outcome.VERSION_READ,ZabbixVersionProtocol.decode(200,contentType,bytes(good("7.0.31")),1).outcome());}
    @Test void duplicateKeysTrailingDataDepthAndOversizeRejected(){for(String raw:List.of(good("7.0.31")+" {}",good("7.0.31").replace("\"id\":1","\"id\":1,\"id\":1"),"[[[[1]]]]"," ".repeat(16385)))assertEquals(Outcome.PROTOCOL_ERROR,decode(raw).outcome());assertEquals(Outcome.PROTOCOL_ERROR,ZabbixVersionProtocol.decode(200,"application/json",null,1).outcome());}
    @Test void strictEnvelopeRejectsExtraAuthFieldsAndAmbiguousResultErrorPairs(){for(String raw:List.of(good("7.0.31").replace("\"id\":1","\"id\":1,\"auth\":\"SYNTHETIC\""),good("7.0.31").replace("\"id\":1","\"id\":1,\"error\":{}"),good("7.0.31").replace("\"2.0\"","\"1.0\""),"{\"jsonrpc\":\"2.0\",\"result\":7,\"id\":1}"))assertEquals(Outcome.PROTOCOL_ERROR,decode(raw).outcome());}
    @Test void structuredApiErrorIsRedactedAndNeverClaimsAvailability(){var r=decode("{\"jsonrpc\":\"2.0\",\"id\":1,\"error\":{\"code\":-32602,\"message\":\"SYNTHETIC_SECRET_NOT_ECHOED\",\"data\":\"SYNTHETIC_CONTEXT\"}}");assertEquals(Outcome.API_ERROR,r.outcome());assertNull(r.apiVersion());assertNull(r.monitoringReady());assertFalse(r.toString().contains("SYNTHETIC"));assertEquals(Outcome.PROTOCOL_ERROR,decode("{\"jsonrpc\":\"2.0\",\"id\":1,\"error\":\"bad\"}").outcome());}
    @Test void loopbackEndpointRequiresExplicitPortAndExactRpcPath(){for(String uri:List.of("http://127.0.0.1:18100/api_jsonrpc.php","http://127.0.0.1:18100/zabbix/api_jsonrpc.php","https://127.0.0.1:18443/api_jsonrpc.php"))assertEquals(URI.create(uri),ZabbixVersionProtocol.requireLoopbackEndpoint(URI.create(uri)));}
    @Test void nonloopbackAliasesCredentialsQueriesFragmentsAndEncodedPathsRejected(){for(String raw:List.of("http://localhost:18100/api_jsonrpc.php","http://127.0.0.2:18100/api_jsonrpc.php","http://remote.invalid:18100/api_jsonrpc.php","http://127.0.0.1/api_jsonrpc.php","http://127.0.0.1:0/api_jsonrpc.php","http://127.0.0.1:65536/api_jsonrpc.php","http://user:SYNTHETIC@127.0.0.1:18100/api_jsonrpc.php","http://127.0.0.1:18100/api_jsonrpc.php?token=SYNTHETIC","http://127.0.0.1:18100/api_jsonrpc.php#fragment","http://127.0.0.1:18100/x/../api_jsonrpc.php","http://127.0.0.1:18100/%61pi_jsonrpc.php","file:///api_jsonrpc.php"))assertThrows(IllegalArgumentException.class,()->ZabbixVersionProtocol.requireLoopbackEndpoint(URI.create(raw)));}
    @Test void resultConstructorCannotTurnUnknownOrOtherVersionsIntoReadiness(){assertThrows(IllegalArgumentException.class,()->new Result(Outcome.VERSION_READ,"8.0.0"));assertThrows(IllegalArgumentException.class,()->new Result(Outcome.HTTP_ERROR,"7.0.31"));assertThrows(IllegalArgumentException.class,()->new Result(Outcome.VERSION_READ,null));}
}
